<script setup lang="ts">
import {Capacitor} from '@capacitor/core';
import {ref,watch,computed} from 'vue';
import {useI18n} from 'vue-i18n';
import {useDashboard,isPublicDemo} from '../stores/dashboard';
import {personalRequest} from '../api/dashboard';
import {isNative} from '../api/transport';
import {NativeHealth} from '../native-health';
import type {HealthSummary} from '../health-types';
const {t}=useI18n();const store=useDashboard();const health=ref<HealthSummary|null>(null);const consent=ref(false);const origins=ref<string[]>([]);const origin=ref('');const busy=ref(false);const message=ref('');let version=0;
const day=computed(()=>({date:store.data!.date,timezone:store.data!.timezone}));
watch(()=>store.data,value=>{health.value=value?.health??null;},{immediate:true});
watch(()=>store.sessionVersion,()=>{version++;consent.value=false;origins.value=[];origin.value='';health.value=null;message.value='';});
async function authorize(){const current=version;busy.value=true;message.value='';try{const available=await NativeHealth.availability();if(current!==version)return;if(available.status!=='available'){message.value='healthUnavailable';return;}const auth=await NativeHealth.authorize();if(current!==version)return;if(auth.status==='denied'){message.value='healthPermissionDenied';return;}const result=await NativeHealth.sources(day.value);if(current!==version)return;origins.value=result.origins;origin.value=result.origins[0]??'';message.value=origins.value.length?'healthReady':'healthNoData';}catch(error){if(current===version){if(error instanceof Error&&error.message==='invalidToken')store.logout();else message.value='healthReadError';}}finally{busy.value=false;}}
async function sync(){if(!origin.value||!consent.value)return;const current=version;const token=store.token;const date=day.value;busy.value=true;try{const reading=await NativeHealth.readDaily({...date,origin:origin.value});if(current!==version)return;if(reading.active_calories_kcal===null&&reading.steps===null&&reading.total_energy_kcal===null){message.value='healthNoData';return;}const value=await personalRequest<HealthSummary>('health/sync',token,{...reading,...date,consent:true,select_source:true});if(current!==version)return;health.value=value;await store.refresh();message.value='';}catch(error){if(current===version){if(error instanceof Error&&error.message==='invalidToken')store.logout();else message.value='healthReadError';}}finally{busy.value=false;}}
async function importWear(){if(!consent.value)return;const current=version;const token=store.token;const date=day.value;busy.value=true;try{const reading=await NativeHealth.readWearDaily(date);if(current!==version)return;const value=await personalRequest<HealthSummary>('health/sync',token,{...reading,...date,consent:true,select_source:true});if(current!==version)return;health.value=value;await store.refresh();message.value='';}catch(error){if(current===version){if(error instanceof Error&&error.message==='invalidToken')store.logout();else message.value='healthReadError';}}finally{busy.value=false;}}
async function disconnect(){const current=version;busy.value=true;try{await personalRequest('health',store.token,undefined,'DELETE');if(current!==version)return;health.value=null;origins.value=[];origin.value='';consent.value=false;message.value='healthDeleted';await store.refresh();if(isNative)try{await NativeHealth.disconnect();}catch{}}catch(error){if(current===version){if(error instanceof Error&&error.message==='invalidToken')store.logout();else message.value='healthReadError';}}finally{busy.value=false;}}
</script>
<template><section class="widget health-widget"><h2>{{t('healthTitle')}}</h2><p v-if="isPublicDemo">{{t('healthDemo')}}</p><template v-else><p>{{t('healthUpstream')}}</p><p v-if="!isNative" class="widget-note">{{t('healthNativeRequired')}}</p><p v-if="health?.status==='stale'" role="status">{{t('healthStale')}}</p><div v-if="health?.daily" class="macro-grid"><div v-for="key in (['active_calories_kcal','steps','total_energy_kcal'] as const)"><span>{{t(key==='steps'?'healthSteps':key==='active_calories_kcal'?'healthActive':'healthTotal')}}</span><strong>{{health.daily[key]===null?t('healthUnknown'):Math.round(health.daily[key]!)}}</strong></div></div><p v-else>{{t('healthNoData')}}</p><p v-if="health?.daily" class="widget-note">{{t('healthSourceNote',{value:health.daily.origin})}} · {{health.daily.collected_at}}</p><template v-if="isNative"><label class="check-label"><input v-model="consent" type="checkbox">{{t('healthConsent')}}</label><button :disabled="busy||!consent" @click="authorize">{{t('healthAuthorize')}}</button><p v-if="Capacitor.getPlatform()==='android'" class="widget-note">{{t('wearHelp')}}</p><button v-if="Capacitor.getPlatform()==='android'" :disabled="busy||!consent" @click="importWear">{{t('wearImport')}}</button><form v-if="origins.length" @submit.prevent="sync"><label>{{t('healthSource')}}<select v-model="origin"><option v-for="item in origins" :key="item">{{item}}</option></select></label><button :disabled="busy||!consent">{{t('healthSync')}}</button></form></template><p v-if="message" role="status">{{t(message)}}</p><button v-if="health?.sources.length" :disabled="busy" @click="disconnect">{{t('healthDisconnect')}}</button><p class="widget-note">{{t('healthPrivacy')}}</p><p class="widget-note">{{t('healthBudget')}}</p></template></section></template>
